/* Signed 9/18/36-bit right shift reference, version 1.
 * Arithmetic right shifts of negative signed integers are
 * a PDP-10 target policy; C89 leaves their result implementation
 * defined. All expectations are generated by Python integers.
 * This exercises the signed shift family omitted by the
 * upstream 20020108-1.c on nine-bit-char targets.
 */
#include <limits.h>
#if CHAR_BIT != 9
#error PDP10 nine-bit-char target expected
#endif
extern void abort(void);
volatile unsigned int fail_id;
static volatile unsigned int shift_v1;
static volatile signed char neg9_v1;
static volatile signed short neg18_v1;
static volatile signed int neg36_v1;

static const signed long expected_min_9_v1[9] = {
    -256L, -128L, -64L, -32L,
    -16L, -8L, -4L, -2L,
    -1L
};

static const signed long expected_min_18_v1[18] = {
    -131072L, -65536L, -32768L, -16384L,
    -8192L, -4096L, -2048L, -1024L,
    -512L, -256L, -128L, -64L,
    -32L, -16L, -8L, -4L,
    -2L, -1L
};

static const signed long expected_min_36_v1[36] = {
    (-34359738367L - 1L), -17179869184L, -8589934592L, -4294967296L,
    -2147483648L, -1073741824L, -536870912L, -268435456L,
    -134217728L, -67108864L, -33554432L, -16777216L,
    -8388608L, -4194304L, -2097152L, -1048576L,
    -524288L, -262144L, -131072L, -65536L,
    -32768L, -16384L, -8192L, -4096L,
    -2048L, -1024L, -512L, -256L,
    -128L, -64L, -32L, -16L,
    -8L, -4L, -2L, -1L
};

int
main(void)
{
    unsigned int i;

    neg9_v1 = -1;
    for (i=0U; i<9U; i++) {
        shift_v1 = i;
        if ((signed int)(neg9_v1 >> shift_v1) != -1) {
            fail_id = 900U + i;
            abort();
        }
    }
    neg9_v1 = -256;
    for (i=0U; i<9U; i++) {
        shift_v1 = i;
        if ((signed long)(neg9_v1 >> shift_v1) !=
            expected_min_9_v1[i]) {
            fail_id = 950U + i;
            abort();
        }
    }

    neg18_v1 = -1;
    for (i=0U; i<18U; i++) {
        shift_v1 = i;
        if ((signed int)(neg18_v1 >> shift_v1) != -1) {
            fail_id = 1800U + i;
            abort();
        }
    }
    neg18_v1 = -131072;
    for (i=0U; i<18U; i++) {
        shift_v1 = i;
        if ((signed long)(neg18_v1 >> shift_v1) !=
            expected_min_18_v1[i]) {
            fail_id = 1850U + i;
            abort();
        }
    }

    neg36_v1 = -1;
    for (i=0U; i<36U; i++) {
        shift_v1 = i;
        if ((signed int)(neg36_v1 >> shift_v1) != -1) {
            fail_id = 3600U + i;
            abort();
        }
    }
    neg36_v1 = (-34359738367L - 1L);
    for (i=0U; i<36U; i++) {
        shift_v1 = i;
        if ((signed long)(neg36_v1 >> shift_v1) !=
            expected_min_36_v1[i]) {
            fail_id = 3650U + i;
            abort();
        }
    }

    return 0;
}
